Q: Python logging error: Unexpected error occurred: cannot schedule new futures after shutdown A: <p>You're seeing &quot;cannot schedule new futures after shutdown&quot; errors in K8s because your application is trying to log messages while Python is shutting down, and the event loop's executor has already been closed</p>
<p>When your pod receives a SIGTERM (K8s shutdown signal), Python starts a shutdown sequence in this order:</p>
<p>event loop's executor shuts down &gt; your application code (or libraries) may still be trying to log &gt; <code>asyncio.run_coroutine_threadsafe()</code> fails because the executor is gone &gt; triggers your exception handler: &quot;cannot schedule new futures after shutdown&quot;</p>
<p>Its less visible locally because you probably shut down more gracefully, but K8s termination is more abrupt</p>
<p>Try smth like this:</p>
<pre><code>import logging
import asyncio
import uuid
from weakref import WeakSet
import aiohttp
import threading
import traceback
import atexit

class HttpHandler(logging.Handler):
    def __init__(self, host: str):
        super().__init__()
        self.host = host
        self.loop = asyncio.new_event_loop()
        self.thread = threading.Thread(
            target=self._run_loop, daemon=False
        )
        self._futures = WeakSet()
        self.is_closing = False
        self._session = None
        self.thread.start()

        atexit.register(self.close)

    def _run_loop(self):
        asyncio.set_event_loop(self.loop)
        self.loop.run_forever()

    async def _get_session(self):
        &quot;&quot;&quot;Reuse a single session instead of creating one per request&quot;&quot;&quot;
        if self._session is None or self._session.closed:
            self._session = aiohttp.ClientSession()
        return self._session

    async def _send(self, payload):
        try:
            session = await self._get_session()
            async with session.post(self.host, json=payload) as resp:
                if resp.status != 200:
                    print(f&quot;Fluent HTTP request failed with payload: {payload} and status: {resp.status}&quot;)
                resp.raise_for_status()
        except aiohttp.ClientError as e:
            print(f&quot;Fluent HTTP request failed with payload: {payload} and error: {e}&quot;)
        except Exception as e:
            print(f&quot;Unexpected error in _send: {e}&quot;)

    def emit(self, record):
        if self.is_closing:
            return

        # Check if loop is still usable
        if self.loop.is_closed() or not self.loop.is_running():
            return

        try:
            payload = self.format(record)
            fut = asyncio.run_coroutine_threadsafe(
                self._send(payload), self.loop
            )
            self._futures.add(fut)
            fut.add_done_callback(self._futures.discard)
        except RuntimeError:
            # Silently ignore if we can't schedule (shutdown in progress)
            pass

    def close(self):
        if self.is_closing:
            return

        self.is_closing = True

        remaining_futures = list(self._futures)
        for fut in remaining_futures:
            try:
                fut.result(timeout=5)
            except Exception:
                pass

        if self._session and not self._session.closed:
            if self.loop.is_running():
                asyncio.run_coroutine_threadsafe(
                    self._session.close(), self.loop
                ).result(timeout=2)

        if self.loop.is_running():
            self.loop.call_soon_threadsafe(self.loop.stop)

        if self.thread.is_alive():
            self.thread.join(timeout=5)

        if not self.loop.is_closed():
            try:
                self.loop.run_until_complete(self.loop.shutdown_asyncgens())
            except Exception:
                pass

            try:
                self.loop.run_until_complete(self.loop.shutdown_default_executor())
            except Exception:
                pass

            try:
                self.loop.close()
            except Exception:
                pass

        super().close()

    def __del__(self):
        pass
</code></pre>
<p>for even better K8s integration, you can handle SIGTERM explicitly:</p>
<pre><code>import signal
import sys

# in the application startup code:
handler = HttpHandler(&quot;http://your-fluentd-endpoint&quot;)
logger.addHandler(handler)

def shutdown_handler(signum, frame):
    print(&quot;Received shutdown signal, closing handlers...&quot;)
    handler.close()
    sys.exit(0)

signal.signal(signal.SIGTERM, shutdown_handler)
signal.signal(signal.SIGINT, shutdown_handler)
</code></pre>
<p>after applying the fix, you can test graceful shutdown. hope this solves it.</p>
